import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"15、【谦】 艮下坤上","description":"周易集注 - 15、【谦】 艮下坤上","frontmatter":{"title":"15、【谦】 艮下坤上","description":"周易集注 - 15、【谦】 艮下坤上"},"headers":[],"relativePath":"zh/classics/jizhu/019.md","filePath":"zh/classics/jizhu/019.md"}'),h={name:"zh/classics/jizhu/019.md"};function l(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_15、【谦】-艮下坤上" tabindex="-1">15、【谦】 艮下坤上 <a class="header-anchor" href="#_15、【谦】-艮下坤上" aria-label="Permalink to “15、【谦】 艮下坤上”">​</a></h1><p>谦者，有而不居之义。山之高，乃屈而居地之下，谦之象也。止于其内，而收敛不伐，顺乎其外，而卑以下人，谦之义也。《序卦》“有大者不可以盈，故受之以谦”，故次大有。</p><p>君子三也，详见乾卦。三爻艮终万物，故曰有终，彖辞明。</p><p>《彖》曰：谦亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦。鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。(上时掌反)</p><p>济者施也，天位乎上，而气则施于下也。光明者，生成万物*，化育昭著，而不可掩也。卑者，地位乎下也。上行者，地气上行，而交乎天也。天尊而下济，谦也，而光明，则亨矣。地卑，谦也，而上行，则亨矣。此言谦之必亨也。亏盈盖谦以气言，变盈流谦以形言。变者倾坏，流者流注卑下之地而增高也。害盈福谦以理言，恶盈好谦以情言，此四句统言天地鬼神人，三才皆好其谦，见谦之所以亨也。逾者过也，言不可久也。尊者，有功有德，谦而不居，愈见其不可及，亦如天之光明也。卑者有功有德，谦而不居，愈见其不可及，亦如地之上行也。夫以尊卑之谦，皆自屈于其始，而光不可逾，皆自伸于其终，此君子之所以有终也。</p><ul><li>“生成万物”原文误作“往成万物”</li></ul><h3 id="《象》曰-地中有山-谦-君子以裒多益寡-称物平施。" tabindex="-1">《象》曰：地中有山，谦，君子以裒多益寡，称物平施。 <a class="header-anchor" href="#《象》曰-地中有山-谦-君子以裒多益寡-称物平施。" aria-label="Permalink to “《象》曰：地中有山，谦，君子以裒多益寡，称物平施。”">​</a></h3><p>上下五阴，地之象也。一阳居中，地中有山之象也。五阴之多人欲也，一阳之寡天理也，君子观此象，裒其人欲之多，益其天理之寡，则廓然大公，物来顺应，物物皆天理，自可以称物平施，无所处而不当矣。裒者减也。</p><p>初六，谦谦君子，用涉大川，吉。</p><p>凡易中有此象，而无此事，无此理者，于此爻涉大川见之，盖金车玉铉之类也。周公立爻辞，止因中爻震木在坎水之上，故有此句。而今就文依理，只得说能谦险亦可济也。</p><p>六柔，谦德也。初卑位也，以谦德而居卑位，谦而又谦也。君子有此谦德，以之济险亦吉矣。故占者用涉大川亦吉。</p><h3 id="《象》曰-谦谦君子-卑以自牧也。" tabindex="-1">《象》曰：谦谦君子，卑以自牧也。 <a class="header-anchor" href="#《象》曰-谦谦君子-卑以自牧也。" aria-label="Permalink to “《象》曰：谦谦君子，卑以自牧也。”">​</a></h3><p>牧养也。谦谦而成其君子，何哉?盖九三劳谦君子，万民所归服者也。二并上与三俱鸣其谦，四则㧑裂其谦，五因谦而利侵伐。初居谦之下，位已卑矣，何所作为哉?惟自养其谦德而已。</p><p>六二，鸣谦，贞吉。</p><p>本卦与小过同，有飞鸟遗音之象，故曰鸣。豫卦亦有小过之象，亦曰鸣。又中爻震为善鸣，鸣者，阳唱而阴和也。荀九家以阴阳相应，故鸣，得之矣。故中孚错小过，九二曰鸣鹤在阴，又曰翰音登于天，皆有鸣之意，鸣鹤《小象》曰，中心愿也，此曰中心得也，言二与三，中心相得，所以相唱和而鸣也。若旧注以谦有闻，则非鸣谦，乃谦鸣矣。若传以德充积于中，见于声音，则上六鸣谦，其志未得，与鸣豫之凶，皆说不去矣。</p><p>六二柔顺中正，相比于三，三盖劳谦君子也，三谦而二和之，与之相从，故有鸣谦之象，正而且吉者也。故其占如此。</p><h3 id="《象》曰-鸣谦贞吉-中心得也。" tabindex="-1">《象》曰：鸣谦贞吉，中心得也。 <a class="header-anchor" href="#《象》曰-鸣谦贞吉-中心得也。" aria-label="Permalink to “《象》曰：鸣谦贞吉，中心得也。”">​</a></h3><p>言六二与三中心相得，非勉强唱和也。</p><p>九三，劳谦，君子有终，吉。</p><p>劳者勤也，即劳之来之之劳。中爻坎为劳卦，虽系辞去声读，然同此劳字也。又中爻水木，有井象，君子以劳民劝相，此劳字之象也。艮终万物，三居艮之终，故以文王卦辞君子有终归之。八卦正位，艮在三，所以此爻极善。有终即万民服，旧注因系辞有功而不德句，遂以为功劳，殊不知劳乎民后方有功，此爻止有劳而不伐意，故万民服。</p><p>九三当谦之时，以一阳而居五阴之中，阳刚得正，盖能劳乎民而谦者也。然虽不伐其劳，而终不能掩其劳。万民归服，岂不有终。故占者吉。</p><h3 id="《象》曰-劳谦君子-万民服也。" tabindex="-1">《象》曰：劳谦君子，万民服也。 <a class="header-anchor" href="#《象》曰-劳谦君子-万民服也。" aria-label="Permalink to “《象》曰：劳谦君子，万民服也。”">​</a></h3><p>阴为民，五阴故曰万民，众阴归之故曰服。</p><p>六四，无不利，㧑谦。</p><p>㧑者裂也，两开之意。六四当上下之际，开裂之象也。㧑谦者，以㧑为谦也。凡一阳五阴之卦，其阳不论位之当否，皆尊其阳而卑其阴，如复之元吉，师之锡命，豫之大有得，比之显比，剥之得舆，皆尊其阳不论其位也。六四才位皆阴，九三劳谦之贤，正万民归服之时，故开裂退避而去，非旧注更当发挥其谦也。</p><p>六四当谦之时，柔而得正，能谦者也，故无不利矣。但劳谦之贤在下，不敢当阳之承，乃避三而去之，故有以㧑为谦之象。占者能此，可谓不违阳阳之则者矣。</p><h3 id="《象》曰-无不利-㧑谦-不违则也。" tabindex="-1">《象》曰：无不利，㧑谦，不违则也。 <a class="header-anchor" href="#《象》曰-无不利-㧑谦-不违则也。" aria-label="Permalink to “《象》曰：无不利，㧑谦，不违则也。”">​</a></h3><p>则者，阳尊阴卑之法则也。㧑而去之，不违尊卑之则矣。</p><p>六五，不富以其邻，利用侵伐，无不利。</p><p>阳称富，小畜五阳，故《小象》曰不独富也。阴皆不富，故泰六四亦曰不富。富与邻皆指三，以者用也，中爻震为长子，三非正应，故称邻。言不用富厚之力，但用长子帅师，而自利用侵伐也。坤为众，中爻震，此爻变离为戈兵，众动戈兵，侵伐之象。此象亦同初六用涉大川，但此则以变爻言也。上六利用行师亦此象。</p><p>五以柔居尊，在上而能谦者也。上能谦则从之者众矣，故有不富以邻，而自利用侵伐之象，然用侵伐者，因其不服而已，若他事亦无不利也。占者有此谦德，斯应是占矣。</p><h3 id="《象》曰-利用侵伐-征不服也。" tabindex="-1">《象》曰：利用侵伐，征不服也。 <a class="header-anchor" href="#《象》曰-利用侵伐-征不服也。" aria-label="Permalink to “《象》曰：利用侵伐，征不服也。”">​</a></h3><p>侵伐非黩武，以其不服，不得已而征之也。</p><p>上六，鸣谦，利用行师，征邑国。</p><p>凡易中言邑国者，皆坤土也。升卦坤在外，故曰升虚邑，晋卦坤在内，故曰维用伐邑，泰之上六曰自邑告命，师上六曰开国承家，复之上六曰以其国君凶，讼九二变坤，曰邑人三百户，益之中爻坤曰为依迁国，夬下体错坤曰告自邑，涣九五变坤，曰涣王居，此曰征邑国，皆因坤土也。</p><p>上六当谦之终，与三为正应，见三之劳谦，亦相从而和之，故亦有鸣谦之象。然六二中正，既与三中心相得，结亲比之好，则三之心志不在上六，而不相得矣。故止可为将行师，征邑国而已，岂能与劳谦君子之贤相为唱和其谦哉。</p><h3 id="《象》曰-鸣谦-志未得也。可用行师-征邑国也。" tabindex="-1">《象》曰：鸣谦，志未得也。可用行师，征邑国也。 <a class="header-anchor" href="#《象》曰-鸣谦-志未得也。可用行师-征邑国也。" aria-label="Permalink to “《象》曰：鸣谦，志未得也。可用行师，征邑国也。”">​</a></h3><p>志未得者，上六与九三心志不相得也，六二与上六皆鸣谦，然六二中心得，上六志未得，所以六二贞吉，而上六止利用行师也。</p>',38)])])}const m=e(h,[["render",l]]);export{_ as __pageData,m as default};
